input.command:
cd "$ARCHON_HORIZON_ROOT"; for i in AJC.rr AJC.rr.adelic AJC.rr.principal; do echo "=== $i"; "$HORIZON_BIN" roadmap show $i --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
for k in ('name','status','owner','milestone','summary','strategy','detail'):
    v=d.get(k)
    if v: print(k.upper(),':',str(v)[:1500])
cs=d.get('comments',[])
for c in cs[-3:]: print('  * ',(c.get('body') or '')[:600])
"; done

cd "$ARCHON_HORIZON_ROOT"; "$HORIZON_BIN" roadmap list --focus AJC.rr --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
items = d if isinstance(d,list) else d.get('items',d)
for it in items:
    print('=====',it.get('name'),it.get('status'),it.get('owner'),it.get('milestone'))
    for k in ('summary','strategy','detail','notes'):
        if it.get(k): print(' ',k.upper(),':',str(it[k])[:1800])
    for c in (it.get('comments') or [])[-2:]:
        print('   * ',(c.get('body') or '')[:500])
"
